# coding: utf-8
import sys,json
from pathlib import Path
sys.path.insert(0,str(Path(__file__).resolve().parents[2]/'scripts'))
from common import ROOT,read_csv
by={r['question_id']:r for r in read_csv('data/questions.csv')}
initial={r['question_id']:r for r in json.loads((ROOT/'config/authored_batches/S7_028_independent_answers.json').read_text())['questions']}
items=[]
def add(q,summary,values,reasons,solution,concept,labels,knowledge,ambiguity='',calculation=False,figure=False,difficulty=2,cites=None,discipline='basic_1_0',law=False,learning=''):
 r=by[q];a=int(initial[q]['independent_answer']);assert len(values)==len(reasons)==5
 items.append(dict(question_id=q,source_sha256=r['source_sha256'],stem=summary,summary=summary,
 conditions={'判断方向':'全候補を比較し最も適切な語又は数値・順位を選ぶ。','原典照合':'25原典画像で22問の全候補、回路接続、FTAゲート、表の列順、数値・不等号を確認。','前提':'事象の独立性、非零根、修復モデル、法令時点と規準適用範囲は解法と疑義欄に区別する。'},
 choices={str(i):dict(value=v,verdict='適合（記載条件内）' if i==a else '不適合',reason=w) for i,(v,w) in enumerate(zip(values,reasons),1)},
 figures='回路、FTA又は候補表を全て原典で照合。元図は転載せず、接続関係と値を独自に記述。' if figure else '設問固有の図なし。数式・全候補を原典画像で照合。',
 ambiguity=ambiguity,evidence=['extracted/pages/'+r['source_year_directory']+'/basic/page_'+str(p).zfill(3)+'.png' for p in range(int(r['source_page']),int(r['source_page_end'])+1)],
 core_concept=summary,required_knowledge=knowledge,solution=solution,independent_answer=initial[q]['independent_answer'],
 independent_solution_note='公式参照前に25原典画像から22初回解答を保存。'+initial[q]['reason']+'22問の公式との一致を確認。数値の概算は本解法で精算するが初回記録は保持。',
 answer_reason=solution,learning_points=learning or '信頼度と稼働率、安全性と機能継続、規準に依存する係数を分ける。論理接続を事象に置き換え、積を使う前に独立性を確認する。',
 theory_references=['theory:dependability:'+x for x in labels],discipline_id=discipline,concept_id=concept,cross_concepts=[],
 classification_reason='原典内容から、信頼性と保全はbasic_1_0、代表安全率はbasic_1_3、製造物責任は設計管理basic_1_4、単体法と多目的最適化はbasic_1_2へ割り当てる。旧分類からの変更理由と値を出版記録に保持。',
 calculation='true' if calculation else 'false',figure='true' if figure else 'false',law='true' if law else 'false',
 evaluation=dict(knowledge_novelty='2' if law else '1',reasoning_steps='3' if calculation else '2',calculation_load='2' if calculation else '0',figure_reading='2' if figure else '0',difficulty=str(difficulty),difficulty_reason='確率と微積分は対象読者の既知知識であるが、論理接続・独立性・用語適用・候補表の照合を要する。法令や前提不足はAstra査読へ残す。'),
 citations=cites if cites is not None else ['reliability_nist_series','reliability_nist_parallel'],foundationality='high',transferability='high'))

def numeric(q,summary,values,result,solution,labels=['series','parallel'],ambiguity='',concept='design_reliability_network',difficulty=2,cites=None):
 a=int(initial[q]['independent_answer'])
 reasons=[('導出値'+result+'に最も近い。' if i==a else '導出値'+result+'と一致せず、本問の接続・条件を満たす数値ではない。') for i in range(1,6)]
 add(q,summary,values,reasons,solution,concept,labels,'直列は全要素成功の共通事象、並列は少なくとも一つ成功の和事象。独立時の積と補集合、確率範囲と丸め。',ambiguity=ambiguity,calculation=True,figure=True,difficulty=difficulty,cites=cites)

indep='原典は要素/路線の独立を明記しない。周辺信頼度だけでは結合確率が決まらず、積の式は独立モデルを補った条件付き解である。公式正答と独立初回を保持する。'
numeric('H23-REG-BASIC-1-1','既存の二路線を直列経路とし、直結路線の追加で全体の信頼度を指定値へ上げる。',
 ['0.52','0.62','0.72','0.82','0.92'],'0.6153846',
 r'東京から大阪まで名古屋経由の成功事象は二路線の両成功である。独立なら \(R_0=0.8\cdot0.6=0.48\)。直結の信頼度を \(x\) とし、旧経路との独立も仮定すると \(R=1-(1-0.48)(1-x)\)。\(R=0.8\) より \(0.52(1-x)=0.2\)、\(x=1-0.2/0.52=0.6153846\)、最も近い0.62の2である。路線の共通災害で同時不通になる場合にこの独立式をそのまま使わない。',ambiguity=indep)
numeric('H24-REG-BASIC-1-1','並列二要素と直列一要素からなる経路へ、もう一経路を並列接続した信頼度を求める。',
 ['0.25','0.60','0.73','0.85','0.91'],'0.8474',
 r'図を内側から読む。独立なら \(R_{12}=1-(1-0.9)(1-0.8)=0.98\)、これと \(R_3=0.5\) の直列は \(0.49\)。\(R_4=0.7\) がこの経路と並列なので \(R=1-(1-0.49)(1-0.7)=0.8474\)。近い0.85の4である。最外側の並列を、全四要素の直列や全四要素の並列と読み替えない。',ambiguity=indep)
numeric('H26-REG-BASIC-1-4','四要素の直並列系と同じ信頼度を持つ三要素直列系の、単体信頼度を逆算する。',
 ['0.87','0.90','0.93','0.96','0.99'],'0.9290521',
 r'独立ならA系の両端の0.9は直列、中央の二つの0.9は並列である。\(R_A=0.9^2[1-(1-0.9)^2]=0.8019\)。B系は同じ信頼度 \(x\) の三要素の直列なので \(x^3=0.8019\)、\(x=0.8019^{1/3}=0.9290521\)。近い0.93の3である。初回記録の概算0.928はそのまま保存し、ここで精算値を示す。',ambiguity=indep)

add('H27-REG-BASIC-1-1','同じ単体信頼度を持つ単独・二要素直列・二要素並列の大小を比較する。',
 ['B>A>C','B>A=C','B=A=C','B<A=C','B<A<C'],
 ['直列Bが単独Aより高いという最初の関係が逆である。','BはAより小さく、AとCも等しくない。','三者は0.81、0.90、0.99で等しくない。','B<Aは合うがA=Cは違う。','0.81<0.90<0.99に一致する。'],
 r'独立性は原典に明記される。単独 \(A=0.9\)、二要素直列 \(B=0.9^2=0.81\)、二要素並列 \(C=1-(1-0.9)^2=0.99\) なので \(B<A<C\)、5である。一般に \(0<r<1\) なら \(r^2<r<2r-r^2\) であり、両端r=0,1では等しくなる。',
 'design_reliability_network',['series','parallel'],'独立二事象、共通/和事象、0<r<1での不等式。',calculation=True,figure=True)

numeric('H28-REG-BASIC-1-1','共通信頼度の未知要素を含む二つの直並列系が等しいとき、全体の信頼度を求める。',
 ['0.857','0.839','0.822','0.805','0.787'],'0.8048747',
 r'独立なら \(R_A=0.9^2[1-(1-x)^2]=0.81(2x-x^2)\)、\(R_B=0.95x^2\)。等式は \(1.62x-1.76x^2=0\)。非零の根を選ぶ場合 \(x=1.62/1.76=0.9204545\)、全体系 \(R=0.95x^2=0.8048747\) なので0.805の4である。ただし原典はx>0を明示せず、x=0でも等式を満たしR=0となる。未知単体xと問われた全体系Rも分ける。',
 ambiguity=indep+'さらに非零信頼度の条件がなくx=0も解である。公式4はx>0を補った解として示す。',difficulty=3)
numeric('H30-REG-BASIC-1-1','未知単体信頼度を含む直並列系と三要素直列系の等式から、系の信頼度を求める。',
 ['0.835','0.857','0.901','0.945','0.966'],'0.9014573',
 r'独立なら \(R_A=0.95^2(2x-x^2)=0.9025(2x-x^2)\)、\(R_B=x^3\)。原典の \(x>0\) を用いて割ると \(x^2+0.9025x-1.805=0\)。正根は \(x=(-0.9025+\sqrt{0.9025^2+4\cdot1.805})/2=0.9660102\)、もう一根は負で不適である。問われる系の信頼度は \(x^3=0.9014573\)、0.901の3である。0.966は単体の値であり全体値ではない。',
 ambiguity=indep,difficulty=3)

numeric('R01-RET-BASIC-1-3','独立な末端故障事象のFTAで、下位ゲートから最上位事象の発生確率を求める。',
 ['0.036','0.038','0.233','0.641','0.804'],'0.035584',
 r'原典は各下流事象の独立を明記する。左枝の下位ORは \(1-0.9^2=0.19\)、その隣のANDは \(0.2^2=0.04\)、これらのORは \(1-(1-0.19)(1-0.04)=0.2224\)。右枝のANDは \(0.4^2=0.16\)。最上位はANDなので \(P=0.2224\cdot0.16=0.035584\)、近い0.036の1である。図は故障事象の木であり、ANDを直列系の「成功」と取り違えない。異なる枝に同じ末端事象を再使用する木では枝間の独立を別途点検する。',
 labels=['fta'],concept='design_fault_tree',difficulty=3,cites=[])
numeric('R02-REG-BASIC-1-6','同じ部品の並列数を増やし、直列部品を含む系で要求信頼度を初めて満たす個数を求める。',
 ['2','3','4','5','nをいくつにしても信頼度0.94以上にならない'],'最小n=4',
 r'独立性が明記される。信頼度0.7のn個並列と0.95の一要素が直列であるから \(R_n=0.95(1-0.3^n)\)。\(R_n\ge0.94\) は \(0.3^n\le1/95\)。\(n\ge2\) の整数を比較すると \(R_2=0.8645\)、\(R_3=0.92435\)、\(R_4=0.942305\)、\(R_5=0.9476915\)。単調増加なので最小は4、候補3である。上限は0.95であり0.94は達成可能である。',
 difficulty=3)
add('R03-REG-BASIC-1-2','同じ三要素の接続順序を変えた五つの系の信頼度を、成功経路から比較する。',
 ['C>B>E>A>D','C>B>A>E>D','C>E>B>D>A','E>D>A>B>C','E>D>C>B>A'],
 ['A=0.916はE=0.846より高く、その順序が逆である。','C=0.956、B=0.926、A=0.916、E=0.846、D=0.776の順位に一致する。','EはBより低く、DはAより低い。','EとDは前三系より低いので上位に置けない。','EとDをCより上位に置く点が違う。'],
 r'独立を前提とする原典の接続を式へ写す。\(A=1-(1-0.9\cdot0.8)(1-0.7)=0.916\)、\(B=1-(1-0.9\cdot0.7)(1-0.8)=0.926\)、\(C=1-(1-0.8\cdot0.7)(1-0.9)=0.956\)。\(D=0.8[1-(1-0.9)(1-0.7)]=0.776\)、\(E=0.9[1-(1-0.8)(1-0.7)]=0.846\)。従ってC>B>A>E>D、2である。単体の値の順だけを見ず、どの要素が一つの独立経路として全体の停止を防げるかを読む。',
 'design_reliability_network',['series','parallel'],'五つの接続の識別、二要素直列経路と一要素並列経路、単体と系の値の区別。',calculation=True,figure=True,difficulty=3)
numeric('R05-REG-BASIC-1-4','三要素のうち二つ以上が動けば成功する多数決系の信頼度の区間を求める。',
 [r'\(0.90\le R\le1.00\)',r'\(0.85\le R<0.90\)',r'\(0.80\le R<0.85\)',r'\(0.75\le R<0.80\)',r'\(0.70\le R<0.75\)'],'0.784',
 r'独立な三要素の単体信頼度は0.7である。成功事象は「ちょうど二つ成功」と「三つ成功」の排反和であるから \(R={3\choose2}0.7^2(1-0.7)+0.7^3=0.441+0.343=0.784\)。\(0.75\le R<0.80\) の4である。少なくとも一つ成功する全並列、全三つ必要な直列、単に二要素だけを選ぶ直列とは異なる。判定器自身の故障は所与モデルに含まれておらず、その信頼性を実装で無条件に保証しない。',
 labels=['voting'],concept='design_reliability_voting',cites=['reliability_nist_voting'])

add('R03-REG-BASIC-1-4','平均運転時間と平均修復時間から、修復可能な装置の長期の稼働割合を導く。',
 [r'\(A/(A-B)\)',r'\(B/(A-B)\)',r'\(A/(A+B)\)',r'\(B/(A+B)\)',r'\(A/B\)'],
 ['周期は差ではなく運転と修復の和であり、B>0なら1を超える場合もある。','周期の分母と、稼働時間の分子がともに違う。','平均運転時間Aを、運転と修復の平均周期A+Bで割った稼働割合である。','同じ二状態モデルでは非稼働率である。','運転/修復の比は稼働の全時間割合ではなく1を超え得る。'],
 r'試験で用いるMTBFを修復完了から次故障までの平均運転時間A、MTTRを平均修復時間Bとして読む。運転と修復を交互に繰り返す二状態系の長期割合は、有限平均と安定した周期モデルのもとで \(\mathcal A=E[T_{\mathrm{up}}]/(E[T_{\mathrm{up}}]+E[T_{\mathrm{down}}])=A/(A+B)\)、3である。指数分布の仮定はこの平均周期による割合には必須でない。待機・補給・計画停止を含める稼働率では分母の非稼働時間を拡張する。MTBFという名前だけで停止時間込みの暦時間間隔を代入しない。',
 'design_availability',['availability'],'平均運転時間、平均非稼働時間、交互修復の周期平均、信頼度R(t)と稼働率の相違。',calculation=True,cites=[])

for q,values,expected in [
 ('H26-REG-BASIC-1-5',['予防・事後・状態監視・定期・経時','定期・事後・経時・状態監視・予防','状態監視・事後・予防・定期・経時','定期・経時・予防・状態監視・事後','予防・定期・状態監視・経時・事後'],['予防','事後','状態監視','定期','経時']),
 ('R01-RET-BASIC-1-6',['予防・事後・劣化基準・状態監視・経時','状態監視・経時・時間計画・定期・予防','状態監視・事後・劣化基準・定期・経時','定期・経時・時間計画・状態監視・事後','予防・事後・時間計画・定期・経時'],['予防','事後','時間計画','定期','経時'])]:
 reasons=[]
 for v in values:
  bad=['第'+str(i+1)+'欄は'+e+'であり'+t+'ではない' for i,(t,e) in enumerate(zip(v.split('・'),expected)) if t!=e]
  reasons.append('。'.join(bad)+'。' if bad else '故障前/後、保全時期の判断基準、定期と経時の対応が一致する。')
 state=q.startswith('H26')
 solution=('故障を防ぐ目的で故障前に行う予防保全と、故障後に回復する事後保全を分ける。状態監視保全は点検値等から状態を評価して必要な処置を行う。時間計画保全では暦や運転時間等で予定を決め、定期的な保全や経時に基づく保全が対応する。'+('本問の第三欄は状態監視、表の五欄は予防・事後・状態監視・定期・経時、1である。' if state else '本問の第三欄は時間計画、表の五欄は予防・事後・時間計画・定期・経時、5である。')+'両年度は第三欄が異なるため、用語が似ているだけで候補を転用しない。状態を確認する点検が定期的であっても、それだけで状態に基づく処置が時間計画保全へ変わるわけではない。')
 add(q,'故障前後と保全時期の決定基準から、予防・事後・状態監視・時間計画の保全を対応させる。',values,reasons,solution,
 'design_maintenance',['maintenance'],'故障前/後、暦・運転時間の予定、状態測定による処置判断、定期点検と処置時期の区別。',figure=True,cites=['maintenance_mlit_2013'])

add('R05-REG-BASIC-1-5','故障時の安全確保、機能縮退、誤操作対策、故障下の機能継続を区別する。',
 ['フェールセーフ・フェールソフト・フールプルーフ・フォールトトレランス','フェールセーフ・フェールソフト・フールプルーフ・フォールトマスキング','フェールソフト・フォールトトレランス・フールプルーフ・フォールトマスキング','フールプルーフ・フォールトトレランス・フェールソフト・フォールトマスキング','フールプルーフ・フェールセーフ・フェールソフト・フォールトトレランス'],
 ['安全側、優先順位付き縮退、人為的誤り対策、故障下での機能継続の四記述に一致する。','最後の一般的能力を、故障影響を外へ現さない一方式であるマスキングに限定している。','アは安全性を維持するフェールセーフ、イは段階的な機能終了のフェールソフトであり、エの一般的能力はトレランスである。','アの故障は人為的誤りのフールプルーフと異なり、イ・ウ・エの対応も違う。','アはフェールセーフ、イはフェールソフト、ウはフールプルーフなので最初の三欄が違う。'],
 '故障しても安全側を保つ性質はフェールセーフである。故障又は故障の切迫時に影響機能を優先順位に従って徐々に終了するのがフェールソフトである。人為的な誤操作を重大な失敗へつなげない設計はフールプルーフ、想定された故障が存在しても機能を継続できる能力はフォールトトレランスである。四つをこの順に置く1を選ぶ。フォールトマスキングは故障影響を冗長性等で外へ現さない方式であり、故障の検出・隔離・回復を含む一般的な耐故障能力と同じ範囲ではない。安全に停止してよい系と停止自体が危険な系では、要求する安全状態を先に定める。',
 'design_fault_handling',['handling'],'機器故障、人為的誤操作、機能縮退、安全状態、耐故障能力と故障影響隠蔽の範囲。',figure=True,cites=['design_mhlw_foolproof','design_mhlw_failsafe','design_nasa_tolerance'])

pl_partial='原典の条文と平成30年消費者庁逐条解説の第1条・第2条を照合した。e-Gov現行本文は取得不能であり、出題年から現行までの全改正履歴は未照合。空欄の独立解と公式正答を保持し、現在の法全体が当時と同じだとはしない。'
for q,values in [
 ('H25-REG-BASIC-1-1',['製造物・欠陥・被害者・機能性','設計物・欠陥・製造者・安全性','製造物・欠陥・被害者・安全性','設計物・破損・被害者・機能性','製造物・破損・製造者・機能性']),
 ('H27-REG-BASIC-1-4',['製造物・欠陥・被害者・機能性','設計物・欠陥・製造者・安全性','製造物・欠陥・被害者・安全性','設計物・破損・被害者・機能性','製造物・破損・製造者・機能性']),
 ('H30-REG-BASIC-1-6',['製造物・故障・被害者・機能性','設計物・欠陥・製造者・安全性','設計物・破損・被害者・信頼性','製造物・欠陥・被害者・安全性','製造物・破損・製造者・機能性'])]:
 expected=['製造物','欠陥','被害者','安全性'];reasons=[]
 for v in values:
  bad=['第'+str(i+1)+'欄は'+e+'であり'+t+'ではない' for i,(t,e) in enumerate(zip(v.split('・'),expected)) if t!=e]
  reasons.append('。'.join(bad)+'。' if bad else '第1条の対象・責任根拠・保護目的、第2条の欠陥の安全性概念に一致する。')
 add(q,'製造物責任法の保護目的と、通常有すべき安全性を欠くという欠陥の意味を整理する。',values,reasons,
 '第1条の対象は製造物、責任の根拠となる性状は欠陥、保護を図る相手は被害者である。第2条の欠陥は、製造物の特性、通常予見される使用形態、引渡時期等を考慮した通常有すべき安全性の不足である。従って製造物・欠陥・被害者・安全性の行を選ぶ。単なる故障、破損、性能や機能の不足が全てこの法の欠陥になるとは限らず、絶対に危険がないという要求でもない。被害者は購入者又は自然人だけへ限定しない。出題当時の原典条文と平成30年解説の比較に基づく空欄判断であり、時効等を含む法全体の現行解説とは区別する。',
 'design_product_liability',['liability'],'第1条の目的、第2条の製造物/欠陥、機能と安全性の違い、引渡時点と予見可能な使用。',ambiguity=pl_partial,figure=True,cites=['design_caa_pl1','design_caa_pl2'],discipline='basic_1_4',law=True,
 learning='法定の欠陥と単なる不調を分け、設計・製造・指示警告の三側面から安全性を検討する。出題時点と現行解説の確認範囲を混同しない。')

add('H23-REG-BASIC-1-5','異なる用途で使われる安全率の代表値を比較し、それぞれの定義と条件を区別する。',
 ['100・6・1000・4','1.5・4・100・6','100・4・1000・6','1.5・6・100・4','10・4・100・6'],
 ['航空機の代表1.5、摂取量評価の代表100という対応と異なる。','玉掛けワイヤロープは6以上であり4ではない。使用時主索の表値も4.0であって6ではない。','航空機、玉掛け、摂取量評価、使用時主索の四代表値との対応が違う。','意図された四代表値1.5・6・100・4に対応する。ただし航空宇宙/薬品という広い対象を一律の規定値とする根拠にはしない。','航空機の代表は1.5、玉掛けは6、対象告示表の使用時主索は4.0なので三欄が違う。'],
 '代表値の意図を、航空機の構造1.5、玉掛けワイヤロープ6、摂取量の毒性評価100、使用時のエレベーター主索4として読むと4である。2011年米国25.303は航空機の限界荷重に原則1.5を掛ける規定であり、ロケット全体の普遍規準ではない。クレーン等安全規則213条は玉掛けワイヤロープの切断荷重/最大荷重を6以上とする。食品安全委員会の2008年説明は残留農薬等のADIを無毒性量から通常100で割る扱いであって治療薬全般の定数ではない。国交省の平成25年改正反映告示表では、限定された主索の常時使用時4.0、設置時5.0、端部は別値である。分母・対象・時点が異なる数値を同じ物理量の絶対的安全余裕として比較しない。',
 'design_safety_factor_scope',['factor'],'限界/終局荷重比、切断荷重/最大荷重、無毒性量/許容摂取量、主索と端部、設置/使用時の区別。',
 ambiguity='航空宇宙と薬品の対象が広すぎ、四値の全称命題は検証できない。主索4.0は平成25年改正反映表で確認したが2011当時版の全条件未照合。公式/独立4を保持して適用範囲を限定。',figure=True,cites=['design_faa_2011','design_mhlw_crane','design_fsc_adi','design_mlit_elevator'],discipline='basic_1_3',law=True,difficulty=3)
add('H29-REG-BASIC-1-2','航空宇宙・玉掛け・薬品の安全率の代表値の順序を、用途の違いを含めて比較する。',
 ['ア>イ>ウ','イ>ウ>ア','ウ>ア>イ','ア>ウ>イ','ウ>イ>ア'],
 ['意図された代表値ではウが最も大きいので逆である。','100のウは6のイより大きい。','1.5のアは6のイより小さい。','1.5のアを100のウより大きくする点が違う。','限定した代表例100>6>1.5に一致する。'],
 'アを航空機構造の原則1.5、イを玉掛けワイヤロープの6、ウをADI算定などの通常100という代表例として読むと、ウ>イ>ア、5である。数値の大きさは同じ破壊荷重比を使った横断的な安全順位ではない。毒性評価では種差と個体差等を補う不確実係数であり、航空機では限界荷重と終局荷重、玉掛けでは切断荷重と最大荷重の比である。治療薬、ロケットの全てに一律の代表値を適用しない。',
 'design_safety_factor_scope',['factor'],'用途別の安全係数定義、基準荷重と毒性評価、代表値と規準値の差。',
 ambiguity='アの航空機/ロケット、ウの摂取薬品の範囲が規準を特定しない。100>6>1.5は限定された代表例の順序として保持し普遍命題にしない。',figure=True,cites=['design_faa_2011','design_mhlw_crane','design_fsc_adi'],discipline='basic_1_3',law=True)

add('H27-REG-BASIC-1-3','許容応力の定義、安全率の代表値、線形弾性の法則と棒の伸びを対応させる。',
 ['÷・2以上・エネルギー・断面積','÷・2以上・フック・断面積','×・1以下・フック・荷重','×・1以下・エネルギー・断面積','÷・2以上・フック・荷重'],
 ['比例の法則はフックであり、同じL,E,Aの伸びは荷重に比例して断面積には反比例する。','最後の比例先は荷重であり断面積ではない。','基準強度に安全率を掛けるのではなく割る。1以下は強度を十分下回る許容応力を作らない。','演算、代表値、法則、比例先がいずれも想定された対応と異なる。','基準強度を割る、設問の代表2以上、フックの法則、荷重比例の四欄が一致する。'],
 r'許容応力を基準の極限強さから定めるモデルは \(\sigma_{\mathrm{allow}}=\sigma_{\mathrm{u}}/n\)。線形弾性域の \(\sigma=E\varepsilon\) はフックの法則であり、一定断面・均一材料の軸荷重棒で \(\Delta L=FL/(EA)\)。L,E,Aを固定すると伸びは荷重Fに比例する。表の÷・2以上・フック・荷重の5である。ただし設問の一般的なnが2以上という代表的説明を、航空機やすべての設計規準へ適用する下限値にしない。',
 'design_safety_factor_scope',['factor'],'基準強さ/安全率、フックの法則、一定断面棒の伸び、固定する長さ・弾性係数・断面積。',
 ambiguity='安全率の一般的な2以上という説明は基準強度・材料・荷重・規準で変わり普遍の下限ではない。公式/独立5を保持して代表的な許容応力モデルと区別する。',figure=True,cites=['struct_mit_beam','design_faa_2011'],discipline='basic_1_3')
add('R07-REG-BASIC-1-3','許容応力を基準強さから定める演算と、静的強度・疲労限度に対する代表安全率を区別する。',
 ['基準強さ/n・1以下・13～20','基準強さ/n・2以上・1.3～2.0','基準強さ/n・2以上・13～20','n/基準強さ・1以下・1.3～2.0','n/基準強さ・2以上・13～20'],
 ['Bの1以下と疲労側13～20が設問の代表値に一致しない。','許容応力の次元と演算、設問で想定する静的2以上・疲労1.3～2.0に対応する。','Cは小数点を落とした13～20であり1.3～2.0ではない。','Aは応力の逆数となり許容応力の次元でなく、Bも違う。','Aの次元とCの小数点が違う。'],
 r'原典の分数は基準強さを安全率nで割る \(\sigma_{\mathrm{allow}}=\sigma_{\mathrm{ref}}/n\) である。nは無次元なので結果は応力の次元を持つ。引張強さを基準とする一般的代表値2以上、疲労限度を基準とする代表範囲1.3～2.0を表に置く2である。13～20という十倍の範囲へ小数点を落とさない。一方、実設計では降伏・座屈・疲労寿命・使用条件と指定規準を確認する必要があり、この代表範囲を全用途の法定下限とはしない。',
 'design_safety_factor_scope',['factor'],'許容応力の次元、基準強さの選定、引張強さと疲労限度、代表安全率と規準。',
 ambiguity='2以上と1.3～2.0は設問の一般的代表値である。全材料・全用途に成立する統一規準を一次資料で確認していない。公式/独立2を保持し普遍の安全条件としない。',figure=True,cites=['struct_mit_beam','struct_nims_data','design_faa_2011'],discipline='basic_1_3')

add('R01-RET-BASIC-1-2','線形計画の解法と双対、多目的設計の相反関係とパレートの意味を整理する。',
 ['シンプレックス・逆・トレードオン・パレート','シンプレックス・逆・トレードオフ・アクティブ','シンプレックス・双対・トレードオフ・パレート','コンプレックス・逆・トレードオン・アクティブ','コンプレックス・双対・トレードオン・パレート'],
 ['線形計画で対応する問題は双対であり逆問題ではない。相反する改善はトレードオフである。','双対を逆とし、非支配解の呼称をアクティブとする点が違う。','単体法、双対、目的間の相反、意図されたパレートに対応する。ただし原文の全目的を同時改善できないという定義は弱パレートにも当てはまる。','単体法のシンプレックス、双対、トレードオフ、パレートの四欄が異なる。','単体法はシンプレックス、相反関係はトレードオフなので二欄が違う。'],
 r'線形目的と線形制約の計画問題の代表解法はシンプレックス（単体）法であり、制約の重みを変数にする対応問題は双対である。複数の目的の改善が相反する関係はトレードオフで、他の可行解に支配されない解がパレート最適解である。表の意図はシンプレックス・双対・トレードオフ・パレートの3である。ただし最小化で「全てを同時に改善」を全成分の厳密減少と読むと弱パレートの条件になる。可行集合 \(\{(0,1),(0,0)\}\) では(0,1)は全成分の厳密減少を受けないが(0,0)に支配され、通常のパレート最適ではない。通常の定義は全成分で悪化せず少なくとも一成分を厳密改善する他解が存在しないことである。',
 'design_multiobjective',['optimization'],'線形計画、基底交換、弱/強双対、可行集合、目的間の相反、支配と弱パレートの論理。',
 ambiguity='原文の「全ての目的関数を同時に改善できない」は全成分の厳密改善を意味すると弱パレートの条件であり通常の非支配性より弱い。初回/公式3と定義上の反例を別々に保持。',figure=True,cites=['design_mit_lp'],discipline='basic_1_2',difficulty=3)

